1	/**
2	 * The landing page's phone: a CSS-3D body with a real DOM app screen on its
3	 * front face.
4	 *
5	 * Replaces two things at once (§1, §3):
6	 *   • the Three.js slab — renderer, geometry, materials, lights, texture loader
7	 *     and perpetual render loop, none of which survive here;
8	 *   • the app/embed.html iframe, whose hashed asset references rot every build
9	 *     and are the actual cause of the blank screen.
10	 *
11	 * The screen is a direct React child, so it cannot drift out of sync with a
12	 * build snapshot and needs no cross-window readiness handshake. Enhanced 3D is
13	 * additive: if the transform layer fails or is unsupported, the screen still
14	 * renders flat rather than going blank.
15	 */
16	import { useEffect, useMemo, useRef, useState } from 'react';
17	import './landing-phone.css';
18	import { SCREEN_H, SCREEN_W } from './tokens';
19	import type { LandingPhoneScene, LandingPhoneState } from './types';
20	import { SCENES, stepsFor } from './scenes/registry';
21	import { createSceneController, finalState, resolveState } from './reducer';
22	
23	export type LandingPhoneDemoProps = {
24	  /** Which frame to show. Callers own the state; the phone is presentational. */
25	  state: LandingPhoneState;
26	  /** Degrees. Driven by scroll on the cinematic phone, by tilt in Industries. */
27	  rotateY?: number;
28	  rotateX?: number;
29	  /** Fit the 390 × 844 screen into the caller's box. */
30	  scale?: number;
31	  /** Reduced motion or Save-Data: show finished frames, skip the build-up. */
32	  still?: boolean;
33	  className?: string;
34	};
35	
36	/**
37	 * Announces only completed scenes, and only when the scene changes — an
38	 * intermediate milestone must not spam the live region (§7.6).
39	 */
40	function useSceneAnnouncement(state: LandingPhoneState): string {
41	  const [message, setMessage] = useState('');
42	  const last = useRef<LandingPhoneScene | null>(null);
43	  useEffect(() => {
44	    const def = SCENES[state.scene];
45	    const complete = state.step >= def.steps - 1;
46	    if (complete && last.current !== state.scene) {
47	      last.current = state.scene;
48	      setMessage(def.label);
49	    } else if (!complete && last.current === state.scene) {
50	      last.current = null;
51	    }
52	  }, [state.scene, state.step]);
53	  return message;
54	}
55	
56	export function LandingPhoneDemo({ state, rotateY = 0, rotateX = 0, scale = 1, still = false, className }: LandingPhoneDemoProps) {
57	  const def = SCENES[state.scene];
58	  const Scene = def.Component;
59	  const announcement = useSceneAnnouncement(state);
60	
61	  return (
62	    <div
63	      className={`lp-phone${className ? ` ${className}` : ''}`}
64	      data-demo-scene={state.scene}
65	      data-demo-step={state.step}
66	      style={{
67	        width: SCREEN_W * scale,
68	        height: SCREEN_H * scale,
69	        transform: `perspective(2200px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
70	      }}
71	    >
72	      <div className="lp-rim" aria-hidden />
73	      <div className="lp-face lp-face-back" aria-hidden style={{ backgroundImage: "url('/assets/shell-back.webp')" }} />
74	      <div className="lp-face" role="img" aria-label={def.label}>
75	        <div
76	          style={{
77	            width: SCREEN_W,
78	            height: SCREEN_H,
79	            transform: scale === 1 ? undefined : `scale(${scale})`,
80	            transformOrigin: 'top left',
81	            position: 'relative',
82	            overflow: 'hidden',
83	            background: '#fff',
84	          }}
85	        >
86	          <Scene step={state.step} still={still} />
87	          <div className="lp-island" aria-hidden />
88	        </div>
89	        <div className="lp-glare" aria-hidden />
90	      </div>
91	      <p
92	        aria-live="polite"
93	        style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap' }}
94	      >
95	        {announcement}
96	      </p>
97	    </div>
98	  );
99	}
100	
101	/**
102	 * Scroll → state for the cinematic phone.
103	 *
104	 * The controller only reports milestone changes, so scrolling does not set
105	 * React state on every frame. `still` viewers jump straight to each scene's
106	 * finished frame instead of watching it assemble.
107	 */
108	export function useStoryScene(progress: number, still = false): LandingPhoneState {
109	  const controller = useMemo(() => createSceneController(stepsFor), []);
110	  const [state, setState] = useState<LandingPhoneState>(() => resolveState(progress, stepsFor));
111	
112	  useEffect(() => {
113	    const resolved = resolveState(progress, stepsFor);
114	    const next = still ? finalState(resolved.scene, stepsFor) : resolved;
115	    const changed = controller.set(next);
116	    if (changed) setState(changed);
117	  }, [progress, still, controller]);
118	
119	  return state;
120	}
121	
122	/**
123	 * Mode-aware entry point for the lazily loaded chunk.
124	 *
125	 * The cinematic phone passes `progress` and lets the controller pick the
126	 * scene; the Industries phone passes an explicit `state` for the selected tab.
127	 * Both render the same scenes from the same registry, so the two phones cannot
128	 * drift apart (§3.3).
129	 *
130	 * This is the chunk's default export: LandingPhoneMount lazy-imports this
131	 * module, so everything below — scenes, primitives, CSS — lands in one chunk
132	 * that is fetched once and never re-fetched when the scene changes.
133	 */
134	export type PhoneStageProps = Omit<LandingPhoneDemoProps, 'state'> & {
135	  progress?: number;
136	  state?: LandingPhoneState;
137	};
138	
139	export function PhoneStage({ progress = 0, state, still = false, ...rest }: PhoneStageProps) {
140	  const scrolled = useStoryScene(progress, still);
141	  return <LandingPhoneDemo {...rest} still={still} state={state ?? scrolled} />;
142	}
143	
144	export default PhoneStage;
