  };

  // ---- phone rig ----
  const rigTo = (x, y, ms) => {
    rig.style.transition = ms ? 'transform ' + ms + 'ms ' + EASE : 'none';
    rig.style.transform = 'translate3d(' + x + 'px,' + y + 'px,0) translate(-50%,-50%)';
  };
  const turnTo = (deg, ms) => {
