1	#!/usr/bin/env node
2	/**
3	 * Transfer-budget gate for the landing phone demo (plan §6).
4	 *
5	 * The budget is a release gate, not an end-of-project optimisation, so this
6	 * runs in CI alongside the tests and exits non-zero the moment a hard limit is
7	 * breached. Sizes are measured compressed, because that is what a visitor
8	 * actually downloads.
9	 *
10	 * Usage:
11	 *   node scripts/verify-landing-phone.mjs              # report + enforce
12	 *   node scripts/verify-landing-phone.mjs --require-wired
13	 *       also fails when the demo chunk is absent from the build, which is the
14	 *       P6 acceptance form of the check.
15	 */
16	import { readFileSync, readdirSync, statSync } from 'node:fs';
17	import { gzipSync, brotliCompressSync, constants } from 'node:zlib';
18	import { join } from 'node:path';
19	
20	const DIST = 'dist/public/assets';
21	const PUBLIC_ASSETS = 'client/public/assets';
22	const requireWired = process.argv.includes('--require-wired');
23	
24	/** target / hard-fail, in bytes. §6 table. */
25	const BUDGET = {
26	  js: { target: 30 * 1024, hard: 35 * 1024, label: 'demo JavaScript (gzip)' },
27	  css: { target: 6 * 1024, hard: 8 * 1024, label: 'demo CSS (gzip)' },
28	  img: { target: 37 * 1024, hard: 40 * 1024, label: 'phone images (raw)' },
29	  total: { target: 70 * 1024, hard: 90 * 1024, label: 'whole phone feature' },
30	};
31	
32	const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
33	const gzip = (buf) => gzipSync(buf, { level: 9 }).length;
34	const brotli = (buf) =>
35	  brotliCompressSync(buf, { params: { [constants.BROTLI_PARAM_QUALITY]: 11 } }).length;
36	
