70	/** Reads the demo's acceptance selectors (added in P0). */
71	const readState = (page) =>
72	  page.evaluate(() => {
73	    const el = document.querySelector('[data-demo-scene]');
74	    return el
75	      ? { scene: el.getAttribute('data-demo-scene'), step: Number(el.getAttribute('data-demo-step') ?? -1) }
76	      : null;
77	  });
78	
79	/** Walks the page top to bottom, recording every distinct state seen. */
80	async function walk(page, samples = 140, reverse = false) {
81	  const seen = [];
82	  const height = await page.evaluate(() => document.body.scrollHeight - window.innerHeight);
83	  for (let i = 0; i <= samples; i++) {
84	    const t = reverse ? 1 - i / samples : i / samples;
85	    await page.evaluate((y) => window.scrollTo(0, y), Math.round(height * t));
86	    await page.waitForTimeout(16);
87	    const s = await readState(page);
88	    if (!s || s.scene === 'shell') continue;
89	    const last = seen[seen.length - 1];
90	    if (!last || last.scene !== s.scene || last.step !== s.step) seen.push(s);
91	  }
92	  return seen;
93	}
94	
95	for (const vp of VIEWPORTS) {
96	  console.log(`\n── ${vp.name} ${vp.width}×${vp.height} ${'─'.repeat(30)}`);
97	  const context = await browser.newContext({ viewport: { width: vp.width, height: vp.height } });
98	  const page = await context.newPage();
99	
100	  const requests = [];
101	  const errors = [];
102	  page.on('request', (r) => requests.push(r.url()));
103	  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
104	  page.on('pageerror', (e) => errors.push(String(e)));
105	  page.on('requestfailed', (r) => errors.push(`request failed: ${r.url()}`));
106	
107	  await page.goto(BASE_URL, { waitUntil: 'networkidle' });
108	
109	  // ── the demo is present at all ────────────────────────────────────────────
110	  const mounted = await page.$('[data-demo-scene]');
111	  if (!mounted) {
112	    check(`${vp.name}: phone demo mounted`, false, 'no [data-demo-scene] — not wired into landing-page.tsx yet');
113	    await context.close();
114	    continue;
115	  }
116	
117	  // ── §6 rule 1: nothing phone-specific before the story approaches ─────────
118	  const earlyPhoneChunk = requests.some((u) => /landing-?phone/i.test(u));
119	  check(`${vp.name}: no phone chunk before the story approaches`, !earlyPhoneChunk,
120	    earlyPhoneChunk ? 'phone chunk fetched on initial load' : '');
121	
122	  const seen = await walk(page);
123	
124	  // ── the story performs, in order ──────────────────────────────────────────
125	  const order = [];
126	  for (const s of seen) if (!order.includes(s.scene)) order.push(s.scene);
127	  check(`${vp.name}: visits every scene in story order`,
128	    JSON.stringify(order) === JSON.stringify(SCENE_ORDER),
129	    order.length ? `saw ${order.join(' → ')}` : 'saw nothing');
130	
131	  // ── every workflow reaches its finished state ─────────────────────────────
132	  const maxStep = new Map();
133	  for (const s of seen) maxStep.set(s.scene, Math.max(maxStep.get(s.scene) ?? -1, s.step));
134	  for (const scene of SCENE_ORDER) {
135	    const reached = maxStep.has(scene) && maxStep.get(scene) > 0;
136	    check(`${vp.name}: ${scene} completes`, reached, reached ? `final step ${maxStep.get(scene)}` : 'never advanced');
137	  }
138	
139	  // ── the screen is never blank ─────────────────────────────────────────────
140	  const painted = await page.evaluate(() => {
141	    const el = document.querySelector('[data-demo-scene]');
142	    if (!el) return { visible: false, children: 0 };
143	    const r = el.getBoundingClientRect();
144	    return { visible: r.width > 100 && r.height > 100, children: el.querySelectorAll('*').length };
145	  });
146	  check(`${vp.name}: phone body visible with a populated screen`,
147	    painted.visible && painted.children > 8, `${painted.children} nodes`);
148	
149	  // ── §6: changing scene costs no network ───────────────────────────────────
150	  const beforeScrub = requests.length;
151	  await walk(page, 40, true);
152	  const added = requests.slice(beforeScrub).filter((u) => !u.startsWith('data:'));
153	  check(`${vp.name}: no new resource when changing scenes`, added.length === 0,
154	    added.length ? added.slice(0, 3).join(', ') : '');
155	
156	  // ── reverse scrolling must not strand a stale scene ───────────────────────
157	  const backward = await walk(page, 140, true);
158	  const backOrder = [];
159	  for (const s of backward) if (!backOrder.includes(s.scene)) backOrder.push(s.scene);
160	  check(`${vp.name}: reverse scroll rewinds cleanly`,
161	    JSON.stringify(backOrder) === JSON.stringify([...SCENE_ORDER].reverse()),
162	    backOrder.length ? `saw ${backOrder.join(' → ')}` : 'saw nothing');
163	
164	  // ── fast jump lands on the right frame ────────────────────────────────────
165	  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
166	  await page.waitForTimeout(120);
167	  const atEnd = await readState(page);
168	  check(`${vp.name}: jump to the end lands on the last scene`,
169	    atEnd?.scene === SCENE_ORDER[SCENE_ORDER.length - 1], atEnd ? `${atEnd.scene}#${atEnd.step}` : 'none');
170	
171	  // ── the request graph is clean ────────────────────────────────────────────
172	  for (const { re, why } of FORBIDDEN) {
173	    const hits = requests.filter((u) => re.test(u));
174	    check(`${vp.name}: no ${why} request`, hits.length === 0, hits.slice(0, 2).join(', '));
