1	/**
2	 * The landing page's phone: a CSS-3D body with a real DOM app screen on its
3	 * front face.
4	 *
5	 * Replaces two things at once (§1, §3):
6	 *   • the Three.js slab — renderer, geometry, materials, lights, texture loader
7	 *     and perpetual render loop, none of which survive here;
8	 *   • the app/embed.html iframe, whose hashed asset references rot every build
9	 *     and are the actual cause of the blank screen.
10	 *
11	 * The screen is a direct React child, so it cannot drift out of sync with a
12	 * build snapshot and needs no cross-window readiness handshake. Enhanced 3D is
13	 * additive: if the transform layer fails or is unsupported, the screen still
14	 * renders flat rather than going blank.
15	 */
16	import { useEffect, useMemo, useRef, useState } from 'react';
17	import './landing-phone.css';
18	import { SCREEN_H, SCREEN_W } from './tokens';
19	import type { LandingPhoneScene, LandingPhoneState } from './types';
20	import { SCENES, stepsFor } from './scenes/registry';
21	import { createSceneController, finalState, resolveState } from './reducer';
22	
23	export type LandingPhoneDemoProps = {
24	  /** Which frame to show. Callers own the state; the phone is presentational. */
25	  state: LandingPhoneState;
26	  /** Degrees. Driven by scroll on the cinematic phone, by tilt in Industries. */
27	  rotateY?: number;
28	  rotateX?: number;
29	  /** Fit the 390 × 844 screen into the caller's box. */
30	  scale?: number;
31	  /** Reduced motion or Save-Data: show finished frames, skip the build-up. */
32	  still?: boolean;
33	  className?: string;
34	};
35	
36	/**
37	 * Announces only completed scenes, and only when the scene changes — an
38	 * intermediate milestone must not spam the live region (§7.6).
39	 */
40	function useSceneAnnouncement(state: LandingPhoneState): string {
41	  const [message, setMessage] = useState('');
42	  const last = useRef<LandingPhoneScene | null>(null);
43	  useEffect(() => {
44	    const def = SCENES[state.scene];
45	    const complete = state.step >= def.steps - 1;
46	    if (complete && last.current !== state.scene) {
47	      last.current = state.scene;
48	      setMessage(def.label);
49	    } else if (!complete && last.current === state.scene) {
50	      last.current = null;
51	    }
52	  }, [state.scene, state.step]);
53	  return message;
54	}
55	
56	export function LandingPhoneDemo({ state, rotateY = 0, rotateX = 0, scale = 1, still = false, className }: LandingPhoneDemoProps) {
57	  const def = SCENES[state.scene];
58	  const Scene = def.Component;
59	  const announcement = useSceneAnnouncement(state);
60	
61	  return (
62	    <div
63	      className={`lp-phone${className ? ` ${className}` : ''}`}
64	      data-demo-scene={state.scene}
65	      data-demo-step={state.step}
66	      style={{
67	        width: SCREEN_W * scale,
68	        height: SCREEN_H * scale,
69	        transform: `perspective(2200px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
70	      }}
71	    >
72	      <div className="lp-rim" aria-hidden />
73	      <div className="lp-face lp-face-back" aria-hidden style={{ backgroundImage: "url('/assets/shell-back.webp')" }} />
74	      <div className="lp-face" role="img" aria-label={def.label}>
75	        <div
76	          style={{
77	            width: SCREEN_W,
78	            height: SCREEN_H,
79	            transform: scale === 1 ? undefined : `scale(${scale})`,
80	            transformOrigin: 'top left',
81	            position: 'relative',
82	            overflow: 'hidden',
83	            background: '#fff',
84	          }}
85	        >
86	          <Scene step={state.step} still={still} />
87	          <div className="lp-island" aria-hidden />
88	        </div>
89	        <div className="lp-glare" aria-hidden />
90	      </div>
91	      <p
92	        aria-live="polite"
93	        style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap' }}
94	      >
95	        {announcement}
96	      </p>
97	    </div>
98	  );
99	}
100	
101	/**
102	 * Scroll → state for the cinematic phone.
103	 *
104	 * The controller only reports milestone changes, so scrolling does not set
105	 * React state on every frame. `still` viewers jump straight to each scene's
106	 * finished frame instead of watching it assemble.
107	 */
108	export function useStoryScene(progress: number, still = false): LandingPhoneState {
109	  const controller = useMemo(() => createSceneController(stepsFor), []);
110	  const [state, setState] = useState<LandingPhoneState>(() => resolveState(progress, stepsFor));
111	
112	  useEffect(() => {
113	    const resolved = resolveState(progress, stepsFor);
114	    const next = still ? finalState(resolved.scene, stepsFor) : resolved;
115	    const changed = controller.set(next);
116	    if (changed) setState(changed);
117	  }, [progress, still, controller]);
118	
119	  return state;
120	}
121	
122	/**
123	 * Mode-aware entry point for the lazily loaded chunk.
124	 *
125	 * The cinematic phone passes `progress` and lets the controller pick the
126	 * scene; the Industries phone passes an explicit `state` for the selected tab.
127	 * Both render the same scenes from the same registry, so the two phones cannot
128	 * drift apart (§3.3).
129	 *
130	 * This is the chunk's default export: LandingPhoneMount lazy-imports this
131	 * module, so everything below — scenes, primitives, CSS — lands in one chunk
132	 * that is fetched once and never re-fetched when the scene changes.
133	 */
134	export type PhoneStageProps = Omit<LandingPhoneDemoProps, 'state'> & {
135	  progress?: number;
136	  state?: LandingPhoneState;
137	};
138	
139	export function PhoneStage({ progress = 0, state, still = false, ...rest }: PhoneStageProps) {
140	  const scrolled = useStoryScene(progress, still);
141	  return <LandingPhoneDemo {...rest} still={still} state={state ?? scrolled} />;
142	}
143	
144	export default PhoneStage;

1	/**
2	 * The landing page's only entry point into the phone demo.
3	 *
4	 * Everything the page needs to know lives here, so wiring the demo in is a
5	 * one-line swap for the dead <iframe> rather than a second pass over
6	 * landing-page.tsx. This module is deliberately tiny and imports nothing from
7	 * the demo chunk — scenes, primitives and CSS all arrive behind the lazy
8	 * boundary below, which is what keeps a visitor who never scrolls to the story
9	 * from downloading them (§6 rules 1–3).
10	 *
11	 * Failure modes are covered by construction, because a blank phone is the bug
12	 * this whole plan exists to fix (§7.1):
13	 *   • chunk still loading → static shell
14	 *   • chunk failed to load → static shell
15	 *   • scene threw while rendering → static shell
16	 *   • no IntersectionObserver → load immediately
17	 *   • Save-Data → no prefetch, and finished frames when it does load
18	 */
19	import { Component, Suspense, lazy, useCallback, useEffect, useState, type ReactNode } from 'react';
20	import { SCREEN_H, SCREEN_W } from './tokens';
21	import type { LandingPhoneScene, LandingPhoneState } from './types';
22	import { useApproaching, useStillPreference, useStoryProgress } from './useStoryProgress';
23	
24	const PhoneStage = lazy(() => import('./LandingPhoneDemo'));
25	
26	/**
27	 * Inline-styled on purpose: the shell is the pre-chunk state, so it must not
28	 * depend on landing-phone.css. It is a few hundred bytes and carries the
29	 * phone's silhouette, not its content.
30	 */
31	function StaticShell({ scale = 1, rotateY = 0, label = 'taptpay app' }: { scale?: number; rotateY?: number; label?: string }) {
32	  return (
33	    <div
34	      role="img"
35	      aria-label={label}
36	      data-demo-scene="shell"
37	      style={{
38	        width: SCREEN_W * scale,
39	        height: SCREEN_H * scale,
40	        borderRadius: 54 * scale,
41	        background: 'linear-gradient(158deg,#0a1656 0%,#040D6D 46%,#0b1a6e 100%)',
42	        boxShadow: '0 40px 120px rgba(4,13,109,0.55), inset 0 0 0 2px rgba(185,203,232,0.35)',
43	        transform: `perspective(2200px) rotateY(${rotateY}deg)`,
44	      }}
45	    />
46	  );
47	}
48	
49	class PhoneBoundary extends Component<{ fallback: ReactNode; children: ReactNode }, { failed: boolean }> {
50	  state = { failed: false };
51	
52	  static getDerivedStateFromError() {
53	    return { failed: true };
54	  }
55	
56	  componentDidCatch(error: unknown) {
57	    // The landing page is marketing, not a workflow: degrade to the shell and
58	    // leave a breadcrumb rather than taking the section down.
59	    if (import.meta.env?.DEV) console.error('[landing-phone] scene failed', error);
60	  }
61	
62	  render() {
63	    return this.state.failed ? this.props.fallback : this.props.children;
64	  }
65	}
66	
67	export type LandingPhoneMountProps = {
68	  /**
69	   * cinematic — scroll drives scene and step across the eight story zones.
70	   * industries — the tab picks the scene; step is driven by the tab's own
71	   * progress or pinned to the finished frame.
72	   */
73	  variant: 'cinematic' | 'industries';
74	  /** Industries only: which scene the selected tab shows. */
75	  scene?: LandingPhoneScene;
76	  /** Industries only: pin to an explicit milestone (e.g. replay controls). */
77	  state?: LandingPhoneState;
78	  scale?: number;
79	  /** Degrees of Y rotation at progress 0 and 1; the phone turns between them. */
80	  spin?: [number, number];
81	  /**
82	   * Industries only: "try it live" — tap-through and replay (§3.3). This is
83	   * local milestone stepping, never live production behaviour.
84	   */
85	  interactive?: boolean;
86	  /** Milestone count for the selected scene; supplied by the caller so the
87	   *  main chunk never imports the registry to find out. */
88	  steps?: number;
89	  className?: string;
90	};
91	
92	export function LandingPhoneMount({
93	  variant, scene, state, scale = 1, spin = [-18, 18], interactive = false, steps, className,
94	}: LandingPhoneMountProps) {
95	  const [ref, near] = useApproaching<HTMLDivElement>('600px');
96	  const { reducedMotion, saveData } = useStillPreference();
97	  const progress = useStoryProgress(ref, near && variant === 'cinematic');
98	
99	  // Tap-through state for the Industries phone. Selecting a different tab
100	  // restarts that workflow from its own first milestone.
101	  const [step, setStep] = useState(0);
102	  useEffect(() => setStep(0), [scene]);
103	  const advance = useCallback(() => {
104	    setStep((s) => (steps && steps > 0 ? (s + 1) % steps : s + 1));
105	  }, [steps]);
106	
107	  const still = reducedMotion || saveData;
108	  // Save-Data viewers get the shell until the story is actually in view, not
109	  // merely approaching, so the chunk is never speculatively fetched for them.
110	  const load = saveData ? near && progress > 0 : near;
111	  const rotateY = variant === 'cinematic' ? spin[0] + (spin[1] - spin[0]) * progress : 0;
112	
113	  const shell = <StaticShell scale={scale} rotateY={rotateY} />;
114	
115	  // An Industries tab that is not being tapped through rests on its finished
116	  // frame, so the tab shows a completed workflow rather than an empty first step.
117	  const restStep = steps && steps > 0 ? steps - 1 : 0;
118	  const industriesState: LandingPhoneState | undefined = scene
119	    ? { scene, step: interactive ? step : restStep }
120	    : undefined;
121	
122	  return (
123	    <div ref={ref} className={className} style={{ width: SCREEN_W * scale, height: SCREEN_H * scale, position: 'relative' }}>
124	      {load ? (
125	        <PhoneBoundary fallback={shell}>
126	          <Suspense fallback={shell}>
127	            <PhoneStage
128	              progress={progress}
129	              state={state ?? industriesState}
130	              rotateY={rotateY}
131	              scale={scale}
132	              still={still}
133	            />
134	          </Suspense>
135	        </PhoneBoundary>
136	      ) : (
137	        shell
138	      )}
139	
140	      {/*
141	        Only the Industries phone is interactive, and it exposes exactly two
142	        controls rather than turning every drawn button into a phantom control
143	        (§7.5). Both are real buttons, so they are keyboard reachable.
144	      */}
145	      {interactive && variant === 'industries' && (
146	        <>
147	          <button
148	            type="button"
149	            onClick={advance}
150	            aria-label={`step through the ${scene ?? 'demo'} workflow`}
151	            style={{ position: 'absolute', inset: 0, background: 'transparent', border: 'none', cursor: 'pointer', padding: 0 }}
152	          />
153	          <button
154	            type="button"
155	            onClick={() => setStep(0)}
156	            style={{
157	              position: 'absolute', bottom: -14, left: '50%', transform: 'translateX(-50%)',
158	              padding: '8px 18px', borderRadius: 999, border: '1px solid rgba(94,157,255,0.5)',
159	              background: 'rgba(4,13,109,0.9)', color: '#5E9DFF', cursor: 'pointer',
160	              font: "600 12px/1 'Outfit', system-ui", letterSpacing: '0.06em',
161	            }}
162	          >
163	            replay
164	          </button>
165	        </>
166	      )}
167	    </div>
168	  );
169	}
170	
171	export default LandingPhoneMount;

